def solve(n: int, edges: List[Tuple[int, int, int]], s: int, t: int) -> int:
    if s == t:
        return 0

    # Create adjacency list
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))

    # Bellman-Ford algorithm to find shortest path
    dist = [float('inf')] * n
    dist[s] = 0

    # Relax all edges n-1 times
    for i in range(n-1):
        updated = False
        for u in range(n):
            if dist[u] == float('inf'):
                continue
            for v, w in graph[u]:
                if dist[v] > dist[u] + w:
                    dist[v] = dist[u] + w
                    updated = True
        if not updated:
            break

    # Check if t is unreachable
    if dist[t] == float('inf'):
        return -1

    return int(dist[t])
